/**
 * Summarize Q3 sales data from ../data/sales_q3.csv
 * (Node.js port of summarize_sales.py)
 */
const fs = require('fs');
const path = require('path');

const DATA_FILE = path.join(__dirname, '..', 'data', 'sales_q3.csv');

const lines = fs.readFileSync(DATA_FILE, 'utf-8').trim().split('\n');
const headers = lines[0].split(',');
const rows = lines.slice(1).map(line => {
  const cols = line.split(',');
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i]);
  return obj;
});

let totalRevenue = 0;
const dealsByRegion = {};
const revenueByRegion = {};
let won = 0, lost = 0, pending = 0;

for (const row of rows) {
  const amount = parseFloat(row.amount);
  const region = row.region;
  const status = row.status;
  dealsByRegion[region] = (dealsByRegion[region] || 0) + 1;
  if (status === 'won') {
    totalRevenue += amount;
    revenueByRegion[region] = (revenueByRegion[region] || 0) + amount;
    won++;
  } else if (status === 'lost') {
    lost++;
  } else {
    pending++;
  }
}

const totalDeals = won + lost + pending;
const winRate = totalDeals ? (won / totalDeals * 100) : 0;

const output = [];
output.push('='.repeat(45));
output.push('  Meridian Analytics — Q3 Sales Summary');
output.push('='.repeat(45));
output.push(`  Total deals worked : ${totalDeals}`);
output.push(`  Won                : ${won}`);
output.push(`  Lost               : ${lost}`);
output.push(`  Pending            : ${pending}`);
output.push(`  Win rate           : ${winRate.toFixed(1)}%`);
output.push(`  Total revenue (won): $${totalRevenue.toLocaleString('en-US', {maximumFractionDigits: 0})}`);
output.push('');
output.push('  Revenue by region (won deals):');

const sortedRegions = Object.entries(revenueByRegion).sort((a, b) => b[1] - a[1]);
for (const [region, rev] of sortedRegions) {
  output.push(`    ${region.padEnd(8)} $${rev.toLocaleString('en-US', {maximumFractionDigits: 0}).padStart(10)}  (${dealsByRegion[region]} deals total)`);
}
output.push('='.repeat(45));

console.log(output.join('\n'));
